const RIT={
perde:[['Perdeyi açıyorsun. Sokak yerli yerinde. İnsanlar işine gidiyor; karşı kaldırımda bir kadın köpeğini gezdiriyor.','Köpek durup sana bakıyor. Kadın bakmıyor.'],['Perde. Sokak. Kadın. Köpek. Köpek bugün sana havlıyor.'],['Kadın karşı kaldırımda durmuş, doğrudan pencerene bakıyor. Sen bakınca başını çeviriyor.'],['Kadın bugün siyah giymiş. Köpek ayaklarının dibine yatmış, kıpırdamıyor.'],['Karşı kaldırım boş. Kadın yok. Köpek yok. Sokak, oyuncuları gelmemiş bir sahne gibi.'],['Kadın yerinde. Pencereye bakıyor ve bu kez başını çevirmiyor. Hafifçe selam veriyor. Sen de veriyorsun; neden, bilmeden.']],
yuz:[['Yüzüne soğuk su çarpıyorsun. Aynadaki adam elli sekiz yaşında. Kemal Soylu. Emekli.','Neyden emekli olduğunu soran olmuyor artık.'],['Soğuk su. Aynadaki adam geceyi iyi geçirmemiş. Sen iyi uyudun oysa. Öyle sanıyorsun.'],['Su buz gibi. Aynadaki adamın gözaltları mor. İkiniz de birbirinize güvenmiyorsunuz.'],['Bugün ayın dokuzu. Bunu neden düşündüğünü bilmiyorsun. Yüzünü iki kere yıkıyorsun.'],['Lavabonun kenarında siyah bir leke. Ovuyorsun; çıkmıyor. Matbaa mürekkebi çıkmaz, bilirsin.','Nereden bilirsin?'],['Ellerin simsiyah. Tırnak diplerine kadar mürekkep. Sabunu bitiriyorsun; su gri akıyor.']],
kahve:[['İki yumurta, tereyağında. Bardağa bir sallama çay. Demlik, Nermin gittiğinden beri dolapta duruyor.'],['Yumurta. Sallama çay. Tereyağı bitmek üzere; bakkala yazdırmalı.'],['Yumurtayı kırıyorsun; sarısı dağılıyor. Aldırmıyorsun.'],['Tek yumurta kalmış. Çayı iki kere sallıyorsun, renk vermiyor.'],['Yumurta yok. Kuru ekmek, çay. Düzen bozuldu bir kere.'],['Dolaptaki demliğe uzun uzun bakıyorsun. Sonra yine sallama çay yapıyorsun. Henüz değil.']],
sigara:['Yumurtan bitmeden paketten bir sarı filtre çekiyorsun. Doktor bırak demişti. Doktor da öldü.','Sarı filtre. Pakette son bir tane. Dün dolu değil miydi bu?','Kahvaltıyı itip sigarayı yakıyorsun. Kibrit üç denemede tutuşuyor.','Sigara. Duman, perdeden giren ışığın içinde bir sütun gibi duruyor.','Sigarayı ters yakıyorsun. Filtre kokusu. Küfrediyorsun.','Sigarayı yakmıyorsun. Parmaklarının arasında çeviriyorsun; kâğıdına mürekkep bulaşıyor.'],
sonra:[['Homurdanıyorsun: «Bu şehirde vatman diye adam mı kaldı…»','Fotoğrafta, kalabalığın gerisinde, sırtı dönük şapkalı bir adam var. Önemsemiyorsun.','Bugün ayın altısı. Maaş günü. Karaköy postanesi öğlene kadar açık.'],['09.17. Duvardaki saate bakıyorsun. Sonra bakmamaya karar veriyorsun.','«Bugün evden çıkmıyorum» diyorsun yüksek sesle.','Sonra paketin boşaldığını fark ediyorsun.'],['Fotoğraftaki adamın yüzü bu kez yarım dönük. Şapkası seninki gibi. Paltosu seninki gibi.','Kararını veriyorsun: Hana gidecek ve yangını önleyeceksin. Bir kere olsun gazete yanılacak.'],['«Kütüphaneye adım atmam» diyorsun. «Bu kadar basit.»','İlk kez gazetenin en altına, künyeye bakıyorsun. Küçücük harfler: «Dizgi ve baskı: Hakikat Matbaası, Babıâli.»','Babıâli. Otuz yıl her sabah yürüdüğün yokuş. On bir yıldır ayak basmadın. Neden otuz yıl yürüdüğünü düşünmek istemiyorsun.'],['İsmail yirmi yıldır tek sabah aksatmadı. Kar yağdı geldi, annesi öldü geldi.','Manşet «abonesi kapı kapı dolaştı» diyor. Abone sensin. Dolaşacaksın demek.'],['Elin kendiliğinden kapının arkasındaki paltoya uzanmak istiyor.']]};
