async function perde(){if(G.ph=='sabah'&&!F('_perde')){set('_perde');R();return D(RIT.perde[G.day-1])}return D(G.day==5?'Karşı kaldırım hâlâ boş.':'Sokak yerli yerinde. Karşı kaldırım, kadın, köpek. Her sabahki resim.')}
async function lavabo(){if(G.ph!='sabah'||F('_yuz'))return D('Aynadaki adam sana bakıyor. Gözünü ilk kaçıran sen oluyorsun.');if(!F('_perde'))return D('Önce perde. Düzen, düzendir.');
 set('_yuz');await D(RIT.yuz[G.day-1]);if(G.day==5)return D('Bekliyorsun. Kapı çalmıyor. Yirmi yıldır ilk kez.');set('_knock');knock(G.day==3?2:3);return D(G.day==3?'Tak. Tak. … Bu sabah iki kere.':'Tak. Tak. Tak. Kapı. Her sabahki gibi, üç kere.')}
