async function masa(){const d=G.day;if(G.ph=='sabah'){if(!F('_kahve'))return D('Masa boş. Önce kahvaltı.');set('_oku');R();await D(RIT.sigara[d-1]);await D('Gazeteyi açıyorsun.');await paper(PAPERS[d-1]);await D(RIT.sonra[d-1]);G.ph='gun';return}
 if(d<7){await paper(PAPERS[d-1]);return D('Kaç kere okursan oku, aynı şeyi yazıyor.')}}
async function saat(){if(has('saat_k')){drop('saat_k');set('saat_yok',0);set('saat_ok');await D(['Saati çivisine asıyorsun. Tık. Tık. Tık. On bir yıldır duymadığın bir ses; oda birden kalabalıklaşıyor.','Akrep hâlâ 09.17’de. Parmağını yelkovana uzatıyorsun.']);
  if(!(await choose(['Saati bugüne ayarla','09.17’de bırak; ama çalışsın']))){set('saat_ayar');return D('Yelkovanı itiyorsun. 09.18. Hiçbir şey yıkılmıyor.')}return D('Elini çekiyorsun. Saat 09.17’den kendi başına yürüyüp gidecek. Bırak, o gitsin.')}
 if(F('saat_yok'))return D('Duvarda saatin yuvarlak izi kalmış. İz bile 09.17’yi gösteriyor sanki.');
 if(G.day>=2&&G.day<6&&G.ph!='sabah'){await D('Saat 09.17. Tık demiyor. Rıza Efendi haklı; duran saat uğur getirmez.');if(!(await choose(['Saati indir; saatçiye götür','Bırak dursun']))){set('saat_yok');give('saat');return D('Saati çivisinden alıp koltuğunun altına sıkıştırıyorsun. Hafif. Yıllar daha ağır olur sanırdın.')}return}
 return D(F('saat_ok')?'Saat çalışıyor. Tık. Tık.':'Saat 09.17. Yıllardır hep 09.17. Tık demiyor.')}
async function cerceve(){if(F('reveal')&&!F('cerceve')){set('cerceve');R();return D(['Çerçeveyi çeviriyorsun.','Nermin. Bayramlık mantosuyla, Karaköy iskelesinde. Gülüyor; fotoğrafı sen çekmiştin.','On bir yıl yüzüstü durdu. Camında tek çizik yok.'])}
 return D(F('cerceve')?'Nermin sana bakıyor. Bakabiliyorsun.':'Komodinin üstünde yüzüstü kapatılmış bir çerçeve. Çevirmiyorsun. Hiç çevirmezsin.')}
async function bed(){const d=G.day;if(G.ph=='sabah')return D('Yatağı düzeltiyorsun. Çarşafın senin tarafın buruşuk; öbür taraf on bir yıldır ütülü gibi.');
 if(d==6)return D('Bu gece uyumayacaksın. İlk kez, bile bile.');if(d==5)return D('Yatamazsın. İsmail kayıp; gazete öyle diyor.');
 if(!F('_ev'))return D(d==2?'Yatıyorsun. Tavan. Saat tıklamıyor ama sen 09.17’yi duyuyorsun. Kalkıyorsun.':'Gün bitmeden yatamazsın. Yatsan da uyuyamazsın.');
 await D('Yorgunsun. Kemiklerine kadar.');if(await choose(['Yat, uyu','Biraz daha ayakta kal']))return;
 $('#fade').classList.add('on');await wait(600);press();await D(NIGHT[d-1]);await nextDay();$('#fade').classList.remove('on')}

